  "Mehr dazu: Erste Hilfe": { en: "More: First aid", es: "Más información: Primeros auxilios", ar: "المزيد: الإسعافات الأولية" },
  "Mehr dazu: Wasser finden & aufbereiten": { en: "More: Finding & treating water", es: "Más información: Encontrar y potabilizar agua", ar: "المزيد: إيجاد المياه ومعالجتها" },
  "Mehr dazu: Nahrung": { en: "More: Food", es: "Más información: Alimentos", ar: "المزيد: الغذاء" },
